let registros=[], filtrados=[], charts={}, ordenacao={campo:"data",direcao:-1}, modoAlternativo=false, temaAtual="burger";
const basesPorTema={burger:null,bakery:null,cafe:null,pizzeria:null};
const el=id=>document.getElementById(id);
const moeda=new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"});
