function numero(v){if(typeof v==="number")return Number.isFinite(v)?v:null;const s=String(v??"").trim().replace(/\s/g,"");if(!s)return null;const n=Number(s.includes(",")?s.replace(/\./g,"").replace(",","."):s);return Number.isFinite(n)?n:null}
function dataVal(v){const s=String(v??"").trim(),m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s);if(!m)return null;const d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));return d.getFullYear()===+m[1]&&d.getMonth()===+m[2]-1&&d.getDate()===+m[3]?d:null}
function parseCsv(text,complete){if(window.Papa){Papa.parse(text,{header:true,skipEmptyLines:true,complete})}else{const linhas=text.trim().split(/\r?\n/),cabecalho=linhas.shift().split(",");complete({data:linhas.map(linha=>{const valores=linha.split(",");return Object.fromEntries(cabecalho.map((campo,i)=>[campo,valores[i]??""]))})})}}
function preparar(linhas){let descartados=0;const saida=[];linhas.forEach((x,i)=>{const data=dataVal(x.data),q=numero(x.quantidade),p=numero(x.preco_unitario);if(!data||q===null||p===null){descartados++;return}saida.push({id_venda:String(x.id_venda??i+1),dataTexto:String(x.data),data,produto:String(x.produto||"Não informado"),categoria:String(x.categoria||"Não informada"),canal:String(x.canal||"Não informado"),periodo:String(x.periodo||"Não informado"),forma_pagamento:String(x.forma_pagamento||"Não informado"),dia_semana:String(x.dia_semana||"Não informado"),quantidade:q,preco_unitario:p,tempo_espera:numero(x.tempo_espera_min),avaliacao:numero(x.avaliacao),faturamento:q*p})});return{saida,descartados}}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function preencher(){const campos=[["categoria","categoriaFiltro","Todas"],["canal","canalFiltro","Todos"],["periodo","periodoFiltro","Todos"],["forma_pagamento","pagamentoFiltro","Todos"]];campos.forEach(([campo,id,titulo])=>{const vals=[...new Set(registros.map(r=>r[campo]))].sort((a,b)=>a.localeCompare(b,"pt-BR"));el(id).innerHTML='<option value="">'+titulo+"</option>"+vals.map(v=>'<option value="'+esc(v)+'">'+esc(v)+"</option>").join("")})}
function filtros(){const ini=el("dataInicial").value,fim=el("dataFinal").value,cat=el("categoriaFiltro").value,canal=el("canalFiltro").value,periodo=el("periodoFiltro").value,pag=el("pagamentoFiltro").value,busca=el("pesquisaTabela").value.toLocaleLowerCase("pt-BR").trim();return registros.filter(r=>(!ini||r.dataTexto>=ini)&&(!fim||r.dataTexto<=fim)&&(!cat||r.categoria===cat)&&(!canal||r.canal===canal)&&(!periodo||r.periodo===periodo)&&(!pag||r.forma_pagamento===pag)&&(!busca||[r.id_venda,r.dataTexto,r.produto,r.categoria,r.canal,r.periodo,r.forma_pagamento,r.dia_semana].join(" ").toLocaleLowerCase("pt-BR").includes(busca)))}
function atualizar(){filtrados=filtros();metricas();todosGraficos();tabela();insight()}
function metricas(){const fat=filtrados.reduce((s,r)=>s+r.faturamento,0),unid=filtrados.reduce((s,r)=>s+r.quantidade,0),ids=new Set(filtrados.map(r=>r.id_venda)),avaliacoes=filtrados.filter(r=>r.avaliacao!==null);el("faturamentoTotal").textContent=moeda.format(fat);el("quantidadeVendas").textContent=num.format(ids.size);el("unidadesVendidas").textContent=num.format(unid);el("ticketMedio").textContent=moeda.format(ids.size?fat/ids.size:0);el("avaliacaoMedia").textContent=avaliacoes.length?(avaliacoes.reduce((s,r)=>s+r.avaliacao,0)/avaliacoes.length).toFixed(1).replace(".",",")+"/5":"—"}
function grupo(campo,valor="faturamento"){return filtrados.reduce((o,r)=>{o[r[campo]]=(o[r[campo]]||0)+(valor==="pedidos"?1:(r[valor]||0));return o},{})}
function cfg(id,tipo,labels,dados,cor,extra={}){if(!window.Chart)return;if(charts[id])charts[id].destroy();const tela=el(id),ctx=tela.getContext("2d"),gradiente=ctx.createLinearGradient(extra.indexAxis==="y"?tela.width:0,0,extra.indexAxis==="y"?0:tela.width,tela.height);gradiente.addColorStop(0,cor);gradiente.addColorStop(1,cores[(cores.indexOf(cor)+1)%cores.length]);const fundo=extra.background||gradiente;charts[id]=new Chart(tela,{type:tipo,data:{labels,datasets:[{label:extra.label||"Faturamento",data:dados,borderColor:cor,backgroundColor:fundo,borderWidth:2,fill:tipo==="line",tension:.35,pointRadius:tipo==="line"?3:0,borderRadius:4}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:extra.indexAxis||"x",plugins:{legend:{display:extra.legend||false,labels:{color:"#9eb9d0",font:{size:10}}},tooltip:{callbacks:{label:c=>" "+(extra.currency?moeda.format(c.parsed.y??c.parsed):num.format(c.parsed.y??c.parsed))}}},scales:tipo==="doughnut"?{}:extra.indexAxis==="y"?{x:{beginAtZero:true,grid:{color:"rgba(122,171,215,.12)"},ticks:{color:"#7d9ab5",font:{size:10},callback:v=>extra.currency?moeda.format(v).replace(",00",""):num.format(v)}},y:{grid:{display:false},ticks:{color:"#7d9ab5",font:{size:10}}}}:{x:{grid:{display:false},ticks:{color:"#7d9ab5",font:{size:10},maxRotation:0}},y:{beginAtZero:true,grid:{color:"rgba(122,171,215,.12)"},ticks:{color:"#7d9ab5",font:{size:10},callback:v=>extra.currency?moeda.format(v).replace(",00",""):num.format(v)}}}}})}
function todosGraficos(){const porMes=grupo("dataTexto");const meses=[...new Set(filtrados.map(r=>r.dataTexto.slice(0,7)))].sort();const rotulo=m=>new Intl.DateTimeFormat("pt-BR",{month:"short",year:"numeric"}).format(new Date(m+"-02"));cfg("graficoMensal","line",meses.map(rotulo),meses.map(m=>filtrados.filter(r=>r.dataTexto.startsWith(m)).reduce((s,r)=>s+r.faturamento,0)),cores[0],{currency:true});
const cat=grupo("categoria");cfg("graficoCategoria","bar",Object.keys(cat),Object.values(cat),cores[1],{currency:true});
const prod=grupo("produto");const top=Object.entries(prod).sort((a,b)=>b[1]-a[1]).slice(0,8);cfg("graficoProduto","bar",top.map(x=>x[0]),top.map(x=>x[1]),cores[2],{currency:true,indexAxis:"y"});
const canal=grupo("canal","pedidos");cfg("graficoCanal","doughnut",Object.keys(canal),Object.values(canal),cores[0],{background:cores,legend:true});
const pag=grupo("forma_pagamento");cfg("graficoPagamento","bar",Object.keys(pag),Object.values(pag),cores[4],{currency:true});
const dias=["Segunda","Terça","Quarta","Quinta","Sexta","Sábado","Domingo"],porDia=grupo("dia_semana","pedidos");cfg("graficoDia","bar",dias,dias.map(d=>porDia[d]||0),cores[5],{label:"Pedidos"})}
function comparar(a,b,c){let x=a[c],y=b[c];if(c==="data"){x=a.data.getTime();y=b.data.getTime()}if(typeof x==="string")return x.localeCompare(y,"pt-BR",{numeric:true});return x-y}
function tabela(){const linhas=[...filtrados].sort((a,b)=>comparar(a,b,ordenacao.campo)*ordenacao.direcao);el("recordCount").textContent=filtrados.length+" de "+registros.length+" registros";el("emptyState").hidden=linhas.length>0;el("tabelaVendas").style.display=linhas.length?"table":"none";el("tabelaCorpo").innerHTML=linhas.slice(0,300).map(r=>"<tr><td>"+esc(r.id_venda)+"</td><td>"+dataBR.format(r.data)+"</td><td>"+esc(r.produto)+"</td><td>"+esc(r.categoria)+"</td><td>"+esc(r.canal)+"</td><td>"+esc(r.periodo)+"</td><td class='numeric'>"+num.format(r.quantidade)+"</td><td class='numeric'>"+moeda.format(r.faturamento)+"</td></tr>").join("")}
function insight(){if(!filtrados.length){el("insightText").textContent="Nenhum registro corresponde à combinação atual.";return}const cat=grupo("categoria"),top=Object.entries(cat).sort((a,b)=>b[1]-a[1])[0],can=grupo("canal","pedidos"),canTop=Object.entries(can).sort((a,b)=>b[1]-a[1])[0];el("insightText").textContent=modoAlternativo?"O canal "+canTop[0]+" concentra "+Math.round(canTop[1]/filtrados.length*100)+"% dos pedidos filtrados.":"A categoria "+top[0]+" lidera a receita com "+moeda.format(top[1])+" no recorte atual."}
function exibirBase(base){registros=base.registros;el("statusText").textContent=base.nome==="BASE ORIGINAL"?"BASE ORIGINAL":base.nome.toUpperCase();el("validationMessage").textContent=base.descartados?base.descartados+" linha(s) descartada(s) por data ou número inválido.":registros.length+" linhas válidas";el("footerInfo").textContent=num.format(registros.length)+" registros carregados";preencher();const datas=registros.map(x=>x.dataTexto).sort();el("dataInicial").min=datas[0]||"";el("dataInicial").max=datas.at(-1)||"";el("dataFinal").min=datas[0]||"";el("dataFinal").max=datas.at(-1)||"";atualizar()}
function carregar(linhas,nome,tema=temaAtual){const r=preparar(linhas);basesPorTema[tema]={registros:r.saida,nome,descartados:r.descartados};if(tema===temaAtual)exibirBase(basesPorTema[tema])}
function limparTemaSemBase(){registros=[];preencher();el("statusText").textContent="SEM BASE";el("validationMessage").textContent="Importe um CSV para este tema.";el("footerInfo").textContent="Nenhum arquivo neste tema";atualizar()}
function limpar(){["dataInicial","dataFinal","categoriaFiltro","canalFiltro","periodoFiltro","pagamentoFiltro","pesquisaTabela"].forEach(id=>el(id).value="");document.querySelectorAll(".quick").forEach(b=>b.classList.toggle("active",b.dataset.channel===""));atualizar()}
function exportar(){if(!filtrados.length)return;const csv=Papa.unparse(filtrados.map(r=>({id_venda:r.id_venda,data:r.dataTexto,produto:r.produto,categoria:r.categoria,canal:r.canal,periodo:r.periodo,quantidade:r.quantidade,preco_unitario:r.preco_unitario,faturamento:Number(r.faturamento.toFixed(2))})));const blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="vendas-visao-filtrada.csv";a.click();URL.revokeObjectURL(a.href)}
["dataInicial","dataFinal","categoriaFiltro","canalFiltro","periodoFiltro","pagamentoFiltro","pesquisaTabela"].forEach(id=>el(id).addEventListener("input",atualizar));el("limparFiltros").addEventListener("click",limpar);el("exportarCsv").addEventListener("click",exportar);el("importarCsv").addEventListener("click",()=>el("arquivoCsv").click());el("arquivoCsv").addEventListener("change",e=>{const f=e.target.files[0];if(f)Papa.parse(f,{header:true,skipEmptyLines:true,complete:r=>carregar(r.data,f.name,temaAtual),error:()=>el("validationMessage").textContent="Erro ao ler o CSV."})});document.querySelectorAll(".quick").forEach(b=>b.addEventListener("click",()=>{el("canalFiltro").value=b.dataset.channel;document.querySelectorAll(".quick").forEach(x=>x.classList.remove("active"));b.classList.add("active");atualizar()}));document.querySelectorAll("th button").forEach(b=>b.addEventListener("click",()=>{const c=b.dataset.sort;ordenacao={campo:c,direcao:ordenacao.campo===c?ordenacao.direcao*-1:1};tabela()}));el("modoLeitura").addEventListener("click",()=>{modoAlternativo=!modoAlternativo;el("modoLeitura").textContent=modoAlternativo?"mostrar categoria":"mostrar canal";insight()});
const TEMAS={burger:{marca:"NEXUS",kicker:"PAINEL DE CONTROLE",titulo:"Veja o pulso da operação.",texto:"Uma leitura interativa das vendas, produtos e canais da hamburgueria.",simbolo:"N",paleta:["#f2c078","#d9824b","#9e3f36","#6f2d32","#e7a35d","#b96a43","#f0d9ad","#7b3f37"]},bakery:{marca:"FORNO & DADOS",kicker:"PAINEL DA PADARIA",titulo:"O aroma dos seus dados.",texto:"Acompanhe fornadas, horários e produtos que saem quentinhos todos os dias.",simbolo:"F",paleta:["#ffd27d","#c97b4b","#e49a67","#b9d879","#f3c49b","#9c6b4e","#f2a65a","#ead0a5"]},cafe:{marca:"CAFÉ & DADOS",kicker:"PAINEL DA CAFETERIA",titulo:"Ideias servidas em números.",texto:"Descubra os horários, produtos e canais que mantêm sua cafeteria em movimento.",simbolo:"C",paleta:["#d9a86c","#8f5f43","#c9875c","#adc987","#e8c08a","#6e4937","#d9896b","#f0d5a7"]},pizzeria:{marca:"PIZZA LAB",kicker:"PAINEL DA PIZZARIA",titulo:"Uma fatia de cada resultado.",texto:"Leia o ritmo dos pedidos e encontre as combinações que fazem sua pizzaria crescer.",simbolo:"P",paleta:["#ffb071","#f46d67","#d7e477","#c83e32","#ffa45b","#e88b5a","#ffcf7a","#a92b27"]}};
function aplicarTema(nome){const tema=TEMAS[nome]||TEMAS.burger;temaAtual=nome;cores=tema.paleta;document.body.dataset.theme=nome;document.querySelector(".brand h1").childNodes[0].textContent=tema.marca+" ";el("heroKicker").textContent=tema.kicker;el("heroTitle").textContent=tema.titulo;el("heroText").textContent=tema.texto;document.querySelector(".brand-symbol").textContent=tema.simbolo;document.querySelectorAll(".theme-option").forEach(botao=>botao.classList.toggle("active",botao.dataset.theme===nome));try{localStorage.setItem("temaDashboard",nome)}catch(erro){}if(basesPorTema[nome])exibirBase(basesPorTema[nome]);else limparTemaSemBase()}
document.querySelectorAll(".theme-option").forEach(botao=>botao.addEventListener("click",()=>aplicarTema(botao.dataset.theme)));
let temaInicial="burger";try{temaInicial=localStorage.getItem("temaDashboard")||"burger"}catch(erro){}aplicarTema(temaInicial);
function carregarReferencia(){const usarArquivo=(url)=>fetch(url).then(res=>{if(!res.ok)throw new Error("CSV não encontrado");return res.text()}).then(texto=>parseCsv(texto,r=>carregar(r.data,"BASE ORIGINAL","burger")));if(location.protocol==="file:"){parseCsv(BASE_CSV,r=>carregar(r.data,"BASE ORIGINAL","burger"))}else{usarArquivo("vendas_hamburgueria.csv").catch(()=>parseCsv(BASE_CSV,r=>carregar(r.data,"BASE ORIGINAL","burger")))}}
carregarReferencia();











